const stats = $("Query 24h Risk Stats").first().json || {};
const total = stats.total_assessments || 0;
const high = stats.high_risk_count || 0;
const moderate = stats.moderate_risk_count || 0;
const low = stats.low_risk_count || 0;
const pending = stats.pending_review_count || 0;
const timestamp = new Date().toISOString();

const subject = `📊 Healthly Daily Risk Summary Digest - ${new Date().toLocaleDateString()}`;
const body = `=====================================================\n📊 DAILY MENTAL HEALTH RISK SUMMARY DIGEST\n=====================================================\n\n24-Hour Clinical Activity Overview:\n------------------------------------\n• Total Assessments Submitted: ${total}\n• High Risk Cases:            ${high}\n• Moderate Risk Cases:        ${moderate}\n• Low Risk Cases:             ${low}\n• Pending Human Reviews:      ${pending}\n\nTimestamp: ${timestamp}\n\nAdmin Portal: http://localhost:3000/admin\n=====================================================\nSystem: Healthly Automated Digest Service (n8n Workflow #2)\n`;

return [{
  json: {
    total_assessments: total,
    high_risk_count: high,
    moderate_risk_count: moderate,
    low_risk_count: low,
    pending_review_count: pending,
    digest_subject: subject,
    digest_body: body,
    status: "DIGEST_GENERATED"
  }
}];

const item = $input.first().json;
console.log('=========================================');
console.log('DAILY RISK DIGEST EMAIL SENT TO ADMIN:');
console.log('SUBJECT: ' + item.digest_subject);
console.log(item.digest_body);
console.log('=========================================');

return [{
  json: {
    ...item,
    email_delivered: true,
    delivered_to: 'admin@healthly.com',
    delivered_at: new Date().toISOString()
  }
}];

const item = $input.first().json;
return [{
  json: {
    workflow: 'Workflow 2: Daily Risk Summary Digest',
    status: 'SUCCESS',
    execution_confirmed: true,
    logged_at: new Date().toISOString(),
    details: item
  }
}];
